        /// <summary>The blinking gothic prompt with gold rules, diamonds and the crimson wax seal (buildTapToContinueBanner).</summary>
        private void BuildTapBanner(VisualElement stage, float offsetX, string subLine, bool calm)
        {
            var banner = new VisualElement { pickingMode = PickingMode.Ignore };
            banner.style.width = 900;
            banner.style.height = 200;
            UomdScreenKit.FromBottom(banner, offsetX, 148 - 40);
            stage.Add(banner);
            const float cx = 450f, cy = 70f;
            void Rule(float x, float y, float w, float h, Color c, float a)
            {
                var r = new VisualElement { pickingMode = PickingMode.Ignore };
                r.style.position = Position.Absolute;
                r.style.left = x;
                r.style.top = y - h / 2f;
                r.style.width = w;
                r.style.height = h;
                r.style.backgroundColor = new Color(c.r, c.g, c.b, a);
                banner.Add(r);
            }
            Rule(cx - 370, cy, 120, 2, UomdThemeTokens.GoldHi, 0.85f);
            Rule(cx + 250, cy, 120, 2, UomdThemeTokens.GoldHi, 0.85f);
            Rule(cx - 330, cy + 6, 70, 1, UomdThemeTokens.Silver, 0.45f);
            Rule(cx + 260, cy + 6, 70, 1, UomdThemeTokens.Silver, 0.45f);
            foreach (float dx in new[] { -236f, 236f })
            {
                var d = new VisualElement { pickingMode = PickingMode.Ignore };
                d.style.position = Position.Absolute;
                d.style.left = cx + dx - 5;
                d.style.top = cy - 5;
                d.style.width = d.style.height = 10;
                d.style.rotate = new Rotate(45);
                d.style.backgroundColor = new Color(UomdThemeTokens.GoldHi.r, UomdThemeTokens.GoldHi.g, UomdThemeTokens.GoldHi.b, 0.95f);
                banner.Add(d);
            }
            var seal = new VisualElement { pickingMode = PickingMode.Ignore };
            seal.style.position = Position.Absolute;
            seal.style.left = cx - 18;
            seal.style.top = cy - 60;
            seal.style.width = seal.style.height = 36;
            seal.style.borderTopLeftRadius = seal.style.borderTopRightRadius = seal.style.borderBottomLeftRadius = seal.style.borderBottomRightRadius = 18;
            seal.style.backgroundColor = new Color(0.620f, 0.106f, 0.204f, 0.95f);
            var rim = new Color(UomdThemeTokens.GoldHi.r, UomdThemeTokens.GoldHi.g, UomdThemeTokens.GoldHi.b, 0.92f);
            seal.style.borderTopColor = seal.style.borderBottomColor = seal.style.borderLeftColor = seal.style.borderRightColor = rim;
            seal.style.borderTopWidth = seal.style.borderBottomWidth = seal.style.borderLeftWidth = seal.style.borderRightWidth = 2;
            banner.Add(seal);
            var prompt = PlaceText(banner, TapToStart, 44, new Color(0.945f, 0.925f, 0.894f), 10f, cy, true);
            prompt.style.unityFontStyleAndWeight = FontStyle.Bold;
            UomdScreenKit.Pulse(prompt, 0.35f, 1600, calm);
            PlaceText(banner, ModeBadge, 21, UomdThemeTokens.GoldHi, 4f, cy + 50, true);
            var sub = PlaceText(banner, subLine, 26, UomdThemeTokens.TextDim, 0f, cy + 82, false);
            sub.style.unityFontStyleAndWeight = FontStyle.Italic;
        }

        private static Label PlaceText(VisualElement parent, string text, float size, Color color, float spacing, float y, bool display)
        {
            var label = UomdScreenKit.Text(parent, text, size, color, spacing);
            if (display) label.AddToClassList("uomd-display");
            label.style.position = Position.Absolute;
            label.style.left = 0;
            label.style.right = 0;
            label.style.top = y - size * 0.7f;
            return label;
        }

        private void FireTap()
        {
            if (_busy) return;
            _router.Audio.PlaySfx("sfx_ui_confirm");
            _ = OnTapToStartAsync();
        }

        /// <summary>Native path of TitleScene.onTapToStart: sign in when possible, then entry flow or resume.</summary>
        private async Awaitable OnTapToStartAsync()
        {
            _busy = true;
            if (Application.platform == RuntimePlatform.Android && !_router.Api.IsSignedIn)
            {
                try
                {
                    string idToken = await _router.PlatformBridge.SignInWithGoogleAsync(UomdPlatformBridgeFactory.GoogleWebClientId);
                    await _router.Api.SignInWithGoogleIdTokenAsync(idToken);
                }
                catch (Exception e)
                {
                    Debug.LogWarning($"[Title] sign-in failed: {e.Message}");
                    UomdUiKit.ShowToast(_root, SignInFailed);
                    _busy = false;
                    return;
                }
            }
            await _router.EntryFlow.ContinueAsync();
        }

        private void ReplayIntro()
        {
            if (_busy) return;
            _busy = true;
            _ = _router.NavigateToAsync(UomdScreenId.Prologue);
        }

        public void OnTick(float deltaTime) { }
        public void OnExit() { }
    }

    /// <summary>
    /// "Before the Road" (port of apps/game/src/scenes/PrologueScene.ts): each shot holds exactly duration_seconds on one
    /// painted plate with a slow camera move, a caption and one narration line typed in step with the Japanese voice.
    /// Plates cross-fade over 1.4 s; the caption block fades during the last 0.65 s of a hold. PAUSE and MUTE are always
    /// there, SKIP only on a replay (first-viewing contract). The shot index is checkpointed so a restart resumes there.
    /// </summary>
    public sealed class PrologueScreenController : IUomdScreenController
    {
        private const float RevealCps = 26f;
        private const int CrossfadeMs = 1400;
        private const int TextFadeMs = 650;
        private const float WaveWidth = 560f;
        private const float BarWidth = 440f;
        private const string CheckpointKey = "uomd.prologue.checkpoint";
        private const string EndTitle = "BEFORE THE ROAD";
        private const string UnavailableTitle = "THE OPENING COULD NOT BE LOADED";
        private const string UnavailableBody = "The story opening \"Before the Road\" did not load on this device. Try again, or continue without it — you can replay it later from the title screen.";

        private readonly UomdSceneRouter _router;
        private VisualElement _root;
        private VisualElement _plates;
        private VisualElement _currentPlate;
        private VisualElement _textBlock;
        private Label _caption;
        private VisualElement _progressFill;
        private VisualElement _waveFill;
        private Label _body;
        private Button _pauseButton;
        private Button _muteButton;
        private PrologueSceneDto[] _scenes = Array.Empty<PrologueSceneDto>();
        private string _fullText = "";
        private float _revealed;
        private float _holdElapsed;
        private float _holdSeconds;
        private bool _textFaded;
        private int _index;
        private bool _paused;
        private bool _done;

        public UomdScreenId ScreenId => UomdScreenId.Prologue;

        public PrologueScreenController(UomdSceneRouter router) => _router = router;

        private bool Calm => _router.Session.ReducedMotion;

        public Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            _root = screenRoot;
            _done = false;
            _paused = false;
            _scenes = _router.Session.PrologueConfig?.scenes ?? Array.Empty<PrologueSceneDto>();
            var stage = UomdScreenKit.Layer(screenRoot, Color.black);
            _plates = UomdScreenKit.Layer(stage);
            BuildOverlay(stage);
            BuildControls(stage);
            if (_scenes.Length == 0)
            {
                Unavailable();
                return UomdAwaitables.Completed();
            }
            int saved = PlayerPrefs.GetInt(CheckpointKey, 0);
            _index = saved > 0 && saved < _scenes.Length && !_router.Session.CanSkipPrologue ? saved - 1 : -1;
            _router.Audio.PlayBgmCue("bgm_prologue_before_the_road");
            Next();
            return UomdAwaitables.Completed();
        }

        private void BuildOverlay(VisualElement stage)
        {
            var shade = UomdScreenKit.Layer(stage);
            UomdScreenKit.VerticalShade(shade, 0, 470, Color.black, 0f, 0.9f, fromBottom: true);
            UomdScreenKit.VerticalShade(shade, 0, 240, Color.black, 0.62f, 0f);
            var border = UomdScreenKit.Layer(shade);
            border.style.left = 24;
            border.style.right = 24;
            border.style.top = 20;
            border.style.bottom = 20;
            var plum = new Color(UomdThemeTokens.PlumHi.r, UomdThemeTokens.PlumHi.g, UomdThemeTokens.PlumHi.b, 0.35f);
            border.style.borderTopColor = border.style.borderBottomColor = border.style.borderLeftColor = border.style.borderRightColor = plum;
            border.style.borderTopWidth = border.style.borderBottomWidth = border.style.borderLeftWidth = border.style.borderRightWidth = 1;
            shade.style.opacity = 0f;
            UomdScreenKit.Fade(shade, 1f, 1100, 0, Calm);

            // progress bar under the caption
            var track = Bar(stage, BarWidth, 3, new Color(UomdThemeTokens.PlumHi.r, UomdThemeTokens.PlumHi.g, UomdThemeTokens.PlumHi.b, 0.45f));
            UomdScreenKit.Centered(track, 0, 128);
            _progressFill = Bar(track, 0, 3, new Color(UomdThemeTokens.GoldHi.r, UomdThemeTokens.GoldHi.g, UomdThemeTokens.GoldHi.b, 0.85f));
            _progressFill.style.position = Position.Absolute;
            _progressFill.style.left = 0;

            _textBlock = UomdScreenKit.Layer(stage);
            _caption = UomdScreenKit.Centered(UomdScreenKit.Text(_textBlock, "", 34, UomdThemeTokens.GoldHi, 9f), 0, 82);
            _caption.AddToClassList("uomd-display");

            const float plaqueTop = UomdScreenKit.RefHeight - 314f;
            var plaque = new VisualElement { pickingMode = PickingMode.Ignore };
            plaque.style.width = 1580;
            plaque.style.height = 210;
            plaque.style.backgroundColor = new Color(0.043f, 0.024f, 0.078f, 0.48f);
            var rim = new Color(UomdThemeTokens.Gold.r, UomdThemeTokens.Gold.g, UomdThemeTokens.Gold.b, 0.28f);
            plaque.style.borderTopColor = plaque.style.borderBottomColor = plaque.style.borderLeftColor = plaque.style.borderRightColor = rim;
            plaque.style.borderTopWidth = plaque.style.borderBottomWidth = plaque.style.borderLeftWidth = plaque.style.borderRightWidth = 1;
            plaque.style.borderTopLeftRadius = plaque.style.borderTopRightRadius = plaque.style.borderBottomLeftRadius = plaque.style.borderBottomRightRadius = 26;
            _textBlock.Add(plaque);
            UomdScreenKit.Centered(plaque, 0, plaqueTop + 105);

            var waveTrack = Bar(_textBlock, WaveWidth, 2, new Color(UomdThemeTokens.PlumHi.r, UomdThemeTokens.PlumHi.g, UomdThemeTokens.PlumHi.b, 0.35f));
            UomdScreenKit.Centered(waveTrack, 0, plaqueTop + 198);
            _waveFill = Bar(waveTrack, 0, 2.5f, new Color(UomdThemeTokens.GoldHi.r, UomdThemeTokens.GoldHi.g, UomdThemeTokens.GoldHi.b, 0.88f));
            _waveFill.style.position = Position.Absolute;
            _waveFill.style.left = 0;

            _body = new Label { pickingMode = PickingMode.Ignore, enableRichText = true };
            _body.style.position = Position.Absolute;
            _body.style.left = new Length(50, LengthUnit.Percent);
            _body.style.top = plaqueTop + 44;
            _body.style.width = 1490;
            _body.style.marginLeft = -745;
            _body.style.fontSize = 46;
            _body.style.color = new Color(0.973f, 0.949f, 0.910f);
            _body.style.whiteSpace = WhiteSpace.Normal;
            _body.style.unityTextAlign = TextAnchor.UpperCenter;
            _textBlock.Add(_body);
        }

        private static VisualElement Bar(VisualElement parent, float width, float height, Color color)
        {
            var bar = new VisualElement { pickingMode = PickingMode.Ignore };
            bar.style.width = width;
            bar.style.height = height;
            bar.style.backgroundColor = color;
            parent.Add(bar);
            return bar;
        }

        private void BuildControls(VisualElement stage)
        {
            _pauseButton = UomdScreenKit.AtLeft(UomdScreenKit.MenuButton(stage, "PAUSE", null, 144, 58, 20, false, TogglePause), 108, 56);
            _muteButton = UomdScreenKit.AtLeft(UomdScreenKit.MenuButton(stage, _router.Audio.Muted ? "UNMUTE" : "MUTE", null, 144, 58, 20, false, ToggleMute), 266, 56);
            // entry contract: no Skip on a first viewing
            if (_router.Session.CanSkipPrologue)
            {
                UomdScreenKit.AtRight(UomdScreenKit.MenuButton(stage, "SKIP", null, 144, 58, 20, false, Finish), 108, 56);
            }
        }

        private static void SetLabel(Button button, string text)
        {
            if (button?.Q<Label>() is Label label) label.text = text;
        }

        private void TogglePause()
        {
            if (_done) return;
            _paused = !_paused;
            _router.Audio.SetPaused(_paused);
            SetLabel(_pauseButton, _paused ? "RESUME" : "PAUSE");
        }

        private void ToggleMute()
        {
            _router.Audio.Muted = !_router.Audio.Muted;
            SetLabel(_muteButton, _router.Audio.Muted ? "UNMUTE" : "MUTE");
        }

        private void Next()
        {
            if (_done) return;
            _index++;
            if (_index >= _scenes.Length)
            {
                Ending();
                return;
            }
            PlayerPrefs.SetInt(CheckpointKey, _index);
            var scene = _scenes[_index] ?? new PrologueSceneDto();
            _holdSeconds = Mathf.Max(0.5f, scene.duration_seconds);
            _holdElapsed = 0f;
            _textFaded = false;
            ShowPlate(scene);
            ShowText(scene);
        }

        private void ShowPlate(PrologueSceneDto scene)
        {
            var catalog = _router.Media.Catalog;
            string path = catalog.Still("prologue_" + scene.id) ?? catalog.Still("prologue_" + scene.visual);
            var plate = UomdScreenKit.Backdrop(_plates, _router.Media, path);
            bool first = _currentPlate == null;
            bool zoomIn = _index % 2 == 0;
            float from = Calm ? 1.04f : zoomIn ? 1.02f : 1.12f;
            float to = Calm ? 1.04f : zoomIn ? 1.12f : 1.02f;
            float drift = Calm ? 0 : _index % 3 == 1 ? 56 : -56;
            float driftY = Calm ? 0 : _index % 2 == 0 ? 16 : -16;
            plate.style.scale = new Scale(new Vector3(from, from, 1f));
            plate.style.marginLeft = -drift;
            plate.style.marginTop = -driftY;
            plate.style.opacity = 0f;
            int holdMs = Mathf.RoundToInt(_holdSeconds * 1000f);
            UomdScreenKit.Fade(plate, 1f, first ? 1700 : CrossfadeMs, 0, Calm);
            if (!Calm)
            {
                UomdScreenKit.ScaleTo(plate, to, holdMs + CrossfadeMs);
                UomdScreenKit.Move(plate, drift, driftY, holdMs + CrossfadeMs, 0, false, EasingMode.EaseInOutSine);
                plate.style.rotate = new Rotate(0);
            }
            var old = _currentPlate;
            _currentPlate = plate;
            if (old != null) UomdScreenKit.After(_plates, CrossfadeMs + 80, () => old.RemoveFromHierarchy());
        }

        private void ShowText(PrologueSceneDto scene)
        {
            _caption.text = (scene.caption_en ?? "").ToUpperInvariant();
            _fullText = scene.text_en ?? "";
            _revealed = 0f;
            _body.text = Reveal(0);
            _waveFill.style.width = 0;
            _textBlock.style.opacity = 1f;
            _caption.style.opacity = 0f;
            UomdScreenKit.Fade(_caption, 1f, (int)(TextFadeMs * 1.6f), 180, Calm, EasingMode.EaseOutCubic);
            _router.Audio.PlayVoiceLine(scene.line_id);
            int total = Mathf.Max(1, _scenes.Length);
            _progressFill.style.width = BarWidth * (_index + 1) / total;
        }

        /// <summary>Visible prefix plus the rest drawn transparent, so line breaks never move while the text types out.</summary>
        private string Reveal(int count)
        {
            count = Mathf.Clamp(count, 0, _fullText.Length);
            string shown = Escape(_fullText.Substring(0, count));
            if (count >= _fullText.Length) return shown;
            return shown + "<alpha=#00>" + Escape(_fullText.Substring(count)) + "</alpha>";
        }

        private static string Escape(string text) => text.Replace("<", "<noparse><</noparse>");

        public void OnTick(float deltaTime)
        {
            if (_done || _paused || _scenes.Length == 0 || _index < 0 || _index >= _scenes.Length) return;
            _holdElapsed += deltaTime;
            if (_revealed < _fullText.Length)
            {
                _revealed = Mathf.Min(_fullText.Length, _revealed + deltaTime * RevealCps);
                _body.text = Reveal(Mathf.FloorToInt(_revealed));
                _waveFill.style.width = Mathf.Round(WaveWidth * Mathf.Min(1f, _revealed / Mathf.Max(1, _fullText.Length)));
            }
            if (!_textFaded && _holdElapsed >= _holdSeconds - TextFadeMs / 1000f)
            {
                _textFaded = true;
                UomdScreenKit.Fade(_textBlock, 0f, TextFadeMs, 0, Calm);
            }
            if (_holdElapsed >= _holdSeconds) Next();
        }

        private void Ending()
        {
            if (_done) return;
            _done = true;
            _router.Audio.StopBgm(1.8f);
            var veil = UomdScreenKit.Layer(_root, new Color(0.020f, 0.012f, 0.039f, 0.86f));
            veil.pickingMode = PickingMode.Position;
            var title = UomdScreenKit.Centered(UomdScreenKit.Text(veil, EndTitle, 52, UomdThemeTokens.GoldHi, 6f), 0, UomdScreenKit.RefHeight / 2f - 110f);
            title.AddToClassList("uomd-display");
            var button = UomdScreenKit.Centered(UomdScreenKit.MenuButton(veil, "CONTINUE", null, 500, 112, 34, true, Finish), 0, UomdScreenKit.RefHeight / 2f + 40f);
            title.style.opacity = button.style.opacity = 0f;
            UomdScreenKit.Fade(title, 1f, 800, 0, Calm);
            UomdScreenKit.Fade(button, 1f, 800, 0, Calm);
        }

        /// <summary>The opening could not load: say so, offer a retry, and move on only when the player chooses to.</summary>
        private void Unavailable()
        {
            _done = true;
            var veil = UomdScreenKit.Layer(_root, new Color(0.020f, 0.012f, 0.039f, 0.9f));
            veil.pickingMode = PickingMode.Position;
            var title = UomdScreenKit.Centered(UomdScreenKit.Text(veil, UnavailableTitle, 46, UomdThemeTokens.GoldHi, 4f), 0, UomdScreenKit.RefHeight / 2f - 170f);
            title.AddToClassList("uomd-display");
            var body = UomdScreenKit.Centered(UomdScreenKit.Text(veil, UnavailableBody, 32, UomdThemeTokens.TextPrimary), 0, UomdScreenKit.RefHeight / 2f - 40f);
            body.style.whiteSpace = WhiteSpace.Normal;
            body.style.width = 1300;
            UomdScreenKit.Centered(UomdScreenKit.MenuButton(veil, "TRY AGAIN", null, 480, 110, 32, true, () => _ = _router.NavigateToAsync(UomdScreenId.Boot)), -280, UomdScreenKit.RefHeight / 2f + 140f);
            UomdScreenKit.Centered(UomdScreenKit.MenuButton(veil, "CONTINUE WITHOUT IT", null, 480, 110, 28, false, Finish), 280, UomdScreenKit.RefHeight / 2f + 140f);
        }

        /// <summary>The prologue counts as seen once the player moves on (its end, Skip on replay, or continue without it).</summary>
        private void Finish()
        {
            _done = true;
            _router.Audio.SetPaused(false);
            _router.Audio.StopVoiceLine();
            PlayerPrefs.DeleteKey(CheckpointKey);
            var progress = _router.Session.Account?.storyProgress;
            if (progress != null) progress.prologueDone = true;
            if (_router.Api.IsSignedIn) _ = RecordPrologueSeen();
            _ = _router.EntryFlow.ContinueAsync();
        }

        private async Awaitable RecordPrologueSeen()
        {
            try
            {
                await _router.Api.PutEntryAsync(true, _router.Session.Account?.tutorialStep ?? 0);
            }
            catch (Exception e)
            {
                Debug.LogWarning($"[Prologue] entry checkpoint not saved: {e.Message}");
            }
        }

        public void OnExit()
        {
            _router.Audio.SetPaused(false);
            _router.Audio.StopVoiceLine();
        }
    }

    /// <summary>
    /// Story scene reader (port of apps/game/src/scenes/StoryScene.ts): the location background, knee-up portraits sized
    /// by canonical stature with the speaker in focus, the name plate, and the light-novel box whose text types in step with
    /// the Japanese voice. Scenes with a "presentation" block follow the cutscene rules (UomdCutscene); AUTO starts on when
    /// the scene asks for it. Tap finishes the line or advances. When the scene ends the entry flow decides what follows.
    /// </summary>
    public sealed class StoryScreenController : IUomdScreenController
    {
        private const float NormalCps = 46f; // CPS.normal outside cutscenes
        private const float BoxY = 886f;

        private sealed class Actor
        {
            public VisualElement Image;
            public string Side;
            public string Emotion;
            public float BaseX;
        }

        private readonly UomdSceneRouter _router;
        private readonly SubtitleSynchronizer _subtitles = new SubtitleSynchronizer();
        private readonly Dictionary<string, Actor> _actors = new Dictionary<string, Actor>(StringComparer.Ordinal);
        private StoryRunner _runner;
        private StorySceneDto _scene;
        private VisualElement _root;
        private VisualElement _stage;
        private VisualElement _background;
        private VisualElement _actorLayer;
        private VisualElement _fadeVeil;
        private VisualElement _namePlate;
        private Label _nameText;
        private Label _body;
        private Label _caret;
        private VisualElement _syncFill;
        private Button _autoButton;
        private Button _skipButton;
        private Button _voiceButton;
        private VisualElement _choiceLayer;
        private StoryEvent _line;
        private string _lastLineId = "";
        private string _prevSpeaker;
        private bool _cutscene;
        private bool _auto;
        private bool _skip;
        private bool _finished;
        private bool _lineDone;
        private bool _waiting;
        private float _pauseLeft;
        private float _autoLeft = -1f;
        private float _waitLeft = -1f;
        private float _voiceSeconds;
        private float _typingElapsed;

        public UomdScreenId ScreenId => UomdScreenId.Story;

        public StoryScreenController(UomdSceneRouter router) => _router = router;

        private bool Calm => _router.Session.ReducedMotion;

        public async Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            _root = screenRoot;
            _finished = false;
            _actors.Clear();
            _prevSpeaker = null;
            _line = null;
            string path = _router.Session.ActiveStoryPath;
            string json;
            try
            {
                json = await _router.Patch.ReadTextAsync(path);
                _scene = JsonUtility.FromJson<StorySceneDto>(json) ?? throw new InvalidOperationException("empty scene");
            }
            catch (Exception e)
            {
                Debug.LogError($"[Story] '{path}' could not load: {e.Message}");
                UomdUiKit.ShowToast(screenRoot, "The story could not be loaded.");
                await _router.EntryFlow.StoryFinishedAsync();
                return;
            }
            _cutscene = json.Contains("\"presentation\"");
            _auto = _cutscene && _scene.presentation != null && _scene.presentation.auto;
            _skip = false;
            _runner = new StoryRunner(_scene);
            _lastLineId = LastLineId(_scene);
            Build(screenRoot);
            SetBackground(_scene.location_id);
            Pump();
        }

        private static string LastLineId(StorySceneDto scene)
        {
            for (int i = scene.commands.Length - 1; i >= 0; i--)
            {
                var c = scene.commands[i];
                if (c != null && (c.op == "say" || c.op == "narrate")) return c.line_id;
            }
            return "";
        }

        private void Build(VisualElement screenRoot)
        {
            _stage = UomdScreenKit.Layer(screenRoot, UomdThemeTokens.Void);
            _stage.pickingMode = PickingMode.Position;
            _stage.RegisterCallback<ClickEvent>(_ => Advance());
            _background = UomdScreenKit.Layer(_stage);
            _actorLayer = UomdScreenKit.Layer(_stage);
            UomdScreenKit.VerticalShade(_stage, 0, UomdScreenKit.RefHeight, UomdThemeTokens.Void, 0.08f, 0.76f);

            // light-novel reader box
            var box = new VisualElement { pickingMode = PickingMode.Ignore };
            box.AddToClassList("uomd-panel");
            box.style.width = 1680;
            box.style.height = 248;
            _stage.Add(box);
            UomdScreenKit.Centered(box, 0, BoxY);
            var rule = new Color(UomdThemeTokens.Gold.r, UomdThemeTokens.Gold.g, UomdThemeTokens.Gold.b, 0.32f);
            AddRect(box, 50, 28, 1580, 1, rule);
            AddRect(box, 50, 220, 1580, 1, rule);
            var syncTrack = AddRect(box, 460, 219, 760, 2, new Color(UomdThemeTokens.Silver.r, UomdThemeTokens.Silver.g, UomdThemeTokens.Silver.b, 0.16f));
            _syncFill = AddRect(syncTrack, 0, 0, 0, 2, UomdThemeTokens.GoldHi);
            _body = new Label { pickingMode = PickingMode.Ignore, enableRichText = true };
            _body.style.position = Position.Absolute;
            _body.style.left = 60;
            _body.style.top = 48;
            _body.style.width = 1560;
            _body.style.fontSize = 41;
            _body.style.color = UomdThemeTokens.TextPrimary;
            _body.style.whiteSpace = WhiteSpace.Normal;
            box.Add(_body);
            _caret = UomdScreenKit.Text(box, "▼", 32, UomdThemeTokens.GoldHi);
            _caret.style.position = Position.Absolute;
            _caret.style.right = 40;
            _caret.style.bottom = 30;
            _caret.style.visibility = Visibility.Hidden;
            UomdScreenKit.Pulse(_caret, 0.2f, 1200, Calm);

            _namePlate = new VisualElement { pickingMode = PickingMode.Ignore };
            _namePlate.AddToClassList("uomd-panel");
            _namePlate.style.width = 490;
            _namePlate.style.height = 68;
            _namePlate.style.justifyContent = Justify.Center;
            _namePlate.style.backgroundColor = new Color(UomdThemeTokens.Crimson.r, UomdThemeTokens.Crimson.g, UomdThemeTokens.Crimson.b, 0.92f);
            _nameText = UomdScreenKit.Text(_namePlate, "", 28, UomdThemeTokens.GoldHi, 2f, bold: true);
            _nameText.AddToClassList("uomd-display");
            _stage.Add(_namePlate);
            _namePlate.style.display = DisplayStyle.None;

            var heading = UomdScreenKit.Text(_stage, _scene.title_en ?? "", 30, UomdThemeTokens.TextDim, 2f);
            heading.AddToClassList("uomd-display");
            heading.style.position = Position.Absolute;
            heading.style.left = 60;
            heading.style.top = 38;

            const float btnW = 144f, btnH = 58f, gap = 12f, skipX = 102f;
            _skipButton = UomdScreenKit.AtRight(UomdScreenKit.MenuButton(_stage, "SKIP", null, btnW, btnH, 20, false, ToggleSkip), skipX, 58);
            _autoButton = UomdScreenKit.AtRight(UomdScreenKit.MenuButton(_stage, "AUTO", null, btnW, btnH, 20, _auto, ToggleAuto), skipX + btnW + gap, 58);
            _voiceButton = UomdScreenKit.AtRight(UomdScreenKit.MenuButton(_stage, "VOICE", null, btnW, btnH, 20, false, ReplayVoice), skipX + 2 * (btnW + gap), 58);
            _voiceButton.style.display = DisplayStyle.None;

            _choiceLayer = UomdScreenKit.Layer(_stage);
            _fadeVeil = UomdScreenKit.Layer(_stage, Color.black);
            _fadeVeil.style.opacity = 0f;
        }

        private static VisualElement AddRect(VisualElement parent, float left, float top, float width, float height, Color color)
        {
            var r = new VisualElement { pickingMode = PickingMode.Ignore };
            r.style.position = Position.Absolute;
            r.style.left = left;
            r.style.top = top;
            r.style.width = width;
            r.style.height = height;
            r.style.backgroundColor = color;
            parent.Add(r);
            return r;
        }

        private void SetBackground(string locationId)
        {
            string path = _router.Media.Catalog.Background(locationId);
            if (path == null) return;
            _background.Clear();
            var bg = UomdScreenKit.Backdrop(_background, _router.Media, path);
            bg.style.scale = new Scale(new Vector3(1.03f, 1.03f, 1f));
            if (!Calm) UomdScreenKit.ScaleTo(bg, 1.08f, 24000);
        }

        /// <summary>Runs runner events until one needs the player or time (a line, a choice, a wait, the end).</summary>
        private void Pump()
        {
            for (int guard = 0; guard < 256 && !_finished; guard++)
            {
                var e = _runner.Next();
                if (e == null || e.type == "end")
                {
                    Complete();
                    return;
                }
                switch (e.type)
                {
                    case "background": SetBackground(e.locationId); break;
                    case "music":
                        if (e.cueId == "stop") _router.Audio.StopBgm(1.6f);
                        else _router.Audio.PlayBgmCue(e.cueId);
                        break;
                    case "fade":
                        UomdScreenKit.Fade(_fadeVeil, e.direction == "out" ? 1f : 0f, Mathf.RoundToInt(Mathf.Max(0.05f, e.seconds) * 1000f), 0, Calm);
                        if (e.direction == "in" && guard == 0) _fadeVeil.style.opacity = 1f;
                        break;
                    case "show": ShowActor(e.character, e.side, "composed"); break;
                    case "hide": HideActor(e.character); break;
                    case "flash": if (!_router.Session.ReduceFlash) Flash(); break;
                    case "wait":
                        _waitLeft = Mathf.Max(0f, e.seconds);
                        return;
                    case "line":
                        ShowLine(e);
                        return;
                    case "choice":
                        ShowChoice(e);
                        return;
                }
            }
        }

        private void Flash()
        {
            var flash = UomdScreenKit.Layer(_stage, new Color(1f, 1f, 1f, 0.55f));
            UomdScreenKit.Fade(flash, 0f, 260);
            UomdScreenKit.After(_stage, 400, () => flash.RemoveFromHierarchy());
        }

        private void ShowActor(string character, string side, string emotion)
        {
            string path = _router.Media.Catalog.Portrait(character, emotion);
            if (path == null) return;
            HideActor(character, immediate: true);
            var stature = UomdCharacterStature.Get(character);
            bool left = side != "right";
            float baseX = left ? 460f : UomdScreenKit.RefWidth - 460f;
            float height = stature.VnTargetHeight;
            float width = height * 2f / 3f; // portraits are 768×1152
            var image = UomdScreenKit.Image(_actorLayer, _router.Media, path, width, height, ScaleMode.ScaleToFit);
            image.style.position = Position.Absolute;
            image.style.left = new Length(left ? 0 : 100, LengthUnit.Percent);
            image.style.marginLeft = (left ? baseX : baseX - UomdScreenKit.RefWidth) - width / 2f;
            image.style.top = stature.VnBaseY - height;
            image.style.backgroundPositionY = new BackgroundPosition(BackgroundPositionKeyword.Bottom);
            // portraits face the centre: flip when the art faces the other way
            bool facesRight = stature.NativeFacing == "right";
            if (facesRight != left) image.style.scale = new Scale(new Vector3(-1f, 1f, 1f));
            image.style.opacity = 0f;
            image.style.translate = new Translate(left ? -90 : 90, 0);
            UomdScreenKit.Fade(image, 0.86f, 950, 0, Calm, EasingMode.EaseOutCubic);
            Slide(image, 0f, 950);
            _actors[character] = new Actor { Image = image, Side = left ? "left" : "right", Emotion = emotion, BaseX = baseX };
        }

        private void Slide(VisualElement image, float x, int ms)
        {
            if (Calm)
            {
                image.style.translate = new Translate(x, 0);
                return;
            }
            image.style.transitionProperty = new List<StylePropertyName> { new StylePropertyName("opacity"), new StylePropertyName("translate") };
            image.style.transitionDuration = new List<TimeValue> { new TimeValue(ms, TimeUnit.Millisecond), new TimeValue(ms, TimeUnit.Millisecond) };
            image.style.transitionTimingFunction = new List<EasingFunction> { new EasingFunction(EasingMode.EaseOutCubic), new EasingFunction(EasingMode.EaseOutCubic) };
            UomdScreenKit.After(image, 16, () => image.style.translate = new Translate(x, 0));
        }

        private void HideActor(string character, bool immediate = false)
        {
            if (!_actors.TryGetValue(character, out var actor)) return;
            _actors.Remove(character);
            if (immediate)
            {
                actor.Image.RemoveFromHierarchy();
                return;
            }
            UomdScreenKit.Fade(actor.Image, 0f, 450, 0, Calm);
            UomdScreenKit.After(_actorLayer, 500, () => actor.Image.RemoveFromHierarchy());
        }

        private void SetEmotion(string character, string emotion)
        {
            if (string.IsNullOrEmpty(emotion) || !_actors.TryGetValue(character, out var actor) || actor.Emotion == emotion) return;
            string current = _router.Media.Catalog.Portrait(character, actor.Emotion);
            string next = _router.Media.Catalog.Portrait(character, emotion);
            actor.Emotion = emotion;
            if (next == null || next == current) return;
            _ = SwapPortrait(actor, next);
        }

        private async Awaitable SwapPortrait(Actor actor, string path)
        {
            var texture = await _router.Media.TextureAsync(path);
            if (texture != null) actor.Image.style.backgroundImage = new StyleBackground(texture);
        }

        /// <summary>Speaker in front at full strength, the others dimmed; narration dims everyone slightly.</summary>
        private void FocusSpeaker(string speaker)
        {
            foreach (var kv in _actors)
            {
                bool active = kv.Key == speaker;
                bool narration = string.IsNullOrEmpty(speaker);
                UomdScreenKit.Fade(kv.Value.Image, active ? 1f : narration ? 0.9f : 0.72f, 360, 0, Calm);
                kv.Value.Image.style.unityBackgroundImageTintColor = active ? Color.white : narration ? new Color(0.91f, 0.878f, 0.949f) : new Color(0.69f, 0.643f, 0.761f);
                if (active) kv.Value.Image.BringToFront();
            }
        }

        private void ShowLine(StoryEvent e)
        {
            _line = e;
            _router.Audio.StopVoiceLine();
            bool narration = e.speaker == "narration";
            bool hasVoice = _router.Media.Catalog.TryGetVoice(e.lineId, out var voice);
            _voiceSeconds = hasVoice ? (float)voice.DurationSeconds : 0f;
            _voiceButton.style.display = hasVoice ? DisplayStyle.Flex : DisplayStyle.None;
            float speakerPause = _scene.presentation != null && _scene.presentation.speaker_pause_seconds >= 0 ? _scene.presentation.speaker_pause_seconds : 1f;
            float rawPause = _cutscene ? UomdCutscene.PauseSeconds(_prevSpeaker, e.speaker, speakerPause) : 0f;
            bool changed = _prevSpeaker != null && _prevSpeaker != e.speaker;
            _pauseLeft = _skip ? 0f : hasVoice ? Mathf.Min(rawPause, changed ? 0.3f : 0.16f) : rawPause;
            _prevSpeaker = e.speaker;

            if (!narration) SetEmotion(e.speaker, e.emotion);
            FocusSpeaker(narration ? "" : e.speaker);
            _namePlate.style.display = narration ? DisplayStyle.None : DisplayStyle.Flex;
            if (!narration)
            {
                bool left = !_actors.TryGetValue(e.speaker, out var actor) || actor.Side == "left";
                _nameText.text = (e.speakerDisplay ?? "").ToUpperInvariant();
                _nameText.style.color = e.speaker == "fadyme" ? new Color(0.886f, 0.824f, 1f) : UomdThemeTokens.GoldHi;
                if (left) UomdScreenKit.AtLeft(_namePlate, 365, 746);
                else UomdScreenKit.AtRight(_namePlate, 365, 746);
                _namePlate.style.right = left ? StyleKeyword.Auto : 365;
                _namePlate.style.left = left ? 365 : StyleKeyword.Auto;
            }
            _body.style.unityFontStyleAndWeight = narration ? FontStyle.Italic : FontStyle.Normal;
            _body.style.color = narration ? new Color(0.875f, 0.831f, 0.933f) : UomdThemeTokens.TextPrimary;
            _body.text = "";
            _caret.style.visibility = Visibility.Hidden;
            _syncFill.style.width = 0;
            _lineDone = false;
            _waiting = true;
            _autoLeft = -1f;
            _typingElapsed = 0f;
            if (_pauseLeft <= 0f) StartTyping();
        }

        private void StartTyping()
        {
            if (_finished || _line == null) return;
            if (!_skip) _router.Audio.PlayVoiceLine(_line.lineId);
            float cps = _cutscene ? UomdCutscene.Cps : NormalCps;
            float reveal = Mathf.Max(_line.text.Length / cps, _voiceSeconds > 0 ? _voiceSeconds * 0.92f : 0f);
            _subtitles.BeginLine(_line.text, _skip ? 0.01f : reveal, Calm || _skip);
            _body.text = Reveal(_subtitles.Tick(0f));
        }

        /// <summary>The shown prefix plus the rest drawn transparent, so wrapping never moves while typing.</summary>
        private string Reveal(string shown)
        {
            string full = _subtitles.FullText;
            if (shown.Length >= full.Length) return Escape(full);
            return Escape(shown) + "<alpha=#00>" + Escape(full.Substring(shown.Length)) + "</alpha>";
        }

        private static string Escape(string text) => text.Replace("<", "<noparse><</noparse>");

        private void FinishTyping()
        {
            if (_line == null) return;
            if (_pauseLeft > 0f)
            {
                _pauseLeft = 0f;
                if (!_skip) _router.Audio.PlayVoiceLine(_line.lineId);
                _subtitles.BeginLine(_line.text, 0.01f, true);
            }
            _subtitles.RevealImmediately();
            _body.text = Escape(_subtitles.FullText);
            _syncFill.style.width = 760;
            _lineDone = true;
            _caret.style.visibility = Visibility.Visible;
            if (_skip) _autoLeft = 0.09f;
            else if (_auto) _autoLeft = AutoHoldSeconds();
        }

        /// <summary>StoryScene.autoHoldMs: voice-synced when the line is voiced, otherwise the cutscene hold table.</summary>
        private float AutoHoldSeconds()
        {
            bool last = _line != null && _line.lineId == _lastLineId;
            float closing = _scene.closing_hold_seconds >= 0 ? _scene.closing_hold_seconds : 0f;
            float? closingOpt = _scene.closing_hold_seconds >= 0 ? closing : (float?)null;
            float? hold = _line != null && _line.holdSeconds > 0 ? _line.holdSeconds : (float?)null;
            if (_voiceSeconds > 0f)
            {
                float synced = Mathf.Max(1.05f, Mathf.Max(0f, _voiceSeconds - _typingElapsed) + 0.72f);
                return last && closingOpt.HasValue ? Mathf.Max(synced, closing) : synced;
            }
            int chars = _subtitles.FullText.Length;
            if (!_cutscene) return (hold ?? 2.4f) + chars * 0.022f;
            return UomdCutscene.HoldSeconds(chars, hold, last, closingOpt);
        }

        private void Advance()
        {
            if (_finished || _choiceLayer.childCount > 0) return;
            _autoLeft = -1f;
            if (!_waiting) return;
            if (_pauseLeft > 0f || !_lineDone)
            {
                FinishTyping();
                return;
            }
            _waiting = false;
            Pump();
        }

        private void ShowChoice(StoryEvent e)
        {
            _choiceLayer.Clear();
            _choiceLayer.pickingMode = PickingMode.Position;
            var column = new VisualElement();
            column.style.alignItems = Align.Center;
            UomdScreenKit.Centered(column, 0, 420);
            _choiceLayer.Add(column);
            if (!string.IsNullOrEmpty(e.prompt))
            {
                var prompt = UomdScreenKit.Text(column, e.prompt, 36, UomdThemeTokens.GoldHi);
                prompt.style.marginBottom = 18;
            }
            foreach (var option in e.options)
            {
                string id = option.id;
                var button = UomdScreenKit.MenuButton(column, option.text, null, 900, 88, 30, true, () =>
                {
                    _choiceLayer.Clear();
                    _choiceLayer.pickingMode = PickingMode.Ignore;
                    _runner.Choose(id);
                    Pump();
                });
                button.style.marginBottom = 14;
                button.style.position = Position.Relative;
            }
        }

        private void ToggleAuto()
        {
            _auto = !_auto;
            SetActive(_autoButton, _auto);
            if (_auto && _lineDone && _waiting) _autoLeft = AutoHoldSeconds();
            if (!_auto) _autoLeft = -1f;
        }

        private void ToggleSkip()
        {
            _skip = !_skip;
            SetActive(_skipButton, _skip);
            if (_skip)
            {
                _router.Audio.StopVoiceLine();
                if (_waiting) FinishTyping();
            }
        }

        private void ReplayVoice()
        {
            if (_line != null) _router.Audio.PlayVoiceLine(_line.lineId);
        }

        private static void SetActive(Button button, bool on)
        {
            if (on) button.AddToClassList("uomd-btn-primary");
            else button.RemoveFromClassList("uomd-btn-primary");
        }

        public void OnTick(float deltaTime)
        {
            if (_finished || _runner == null) return;
            if (_waitLeft >= 0f)
            {
                _waitLeft -= deltaTime;
                if (_waitLeft < 0f) Pump();
                return;
            }
            if (_line == null || !_waiting) return;
            if (_pauseLeft > 0f)
            {
                _pauseLeft -= deltaTime;
                if (_pauseLeft <= 0f) StartTyping();
                return;
            }
            if (!_lineDone)
            {
                _typingElapsed += deltaTime;
                _body.text = Reveal(_subtitles.Tick(deltaTime));
                float total = Mathf.Max(0.01f, _subtitles.TotalDuration);
                _syncFill.style.width = 760f * Mathf.Clamp01(_typingElapsed / total);
                if (_subtitles.IsComplete) FinishTyping();
                return;
            }
            if (_autoLeft >= 0f)
            {
                _autoLeft -= deltaTime;
                if (_autoLeft < 0f) Advance();
            }
        }

        private void Complete()
        {
            if (_finished) return;
            _finished = true;
            int holdOut = _scene.scene_id == "tutorial_t3_after" ? 2200 : 1200;
            UomdScreenKit.Fade(_fadeVeil, 1f, holdOut, 0, false);
            UomdScreenKit.After(_stage, holdOut, () => _ = _router.EntryFlow.StoryFinishedAsync());
        }

        public void OnExit()
        {
            _router.Audio.StopVoiceLine();
        }
    }

    /// <summary>
    /// Battle screen on the real deterministic engine (Uomd.Combat.Battle, a bit-exact port of @uomd/combat), presented like
    /// apps/game/src/scenes/BattleScene.ts: the location backdrop, the afk_faithful formation, SD chibi frame animation,
    /// plates with HP/Focus, the turn marker, skill cards (first tap selects, a second tap or a target confirms), event playback
    /// (strikes, floating numbers, heals, shields, defeats, waves) and the result. The recorded actions replay to the same
    /// logHash the server re-simulates.
    /// </summary>
    public sealed class BattleScreenController : IUomdScreenController
    {
        private const float CardWidth = 286f, CardHeight = 88f, CardGap = 36f;

        private readonly UomdSceneRouter _router;
        private readonly List<PlayerAction> _actions = new List<PlayerAction>();
        private readonly Dictionary<string, BattleUnitView> _views = new Dictionary<string, BattleUnitView>(StringComparer.Ordinal);
        private readonly Dictionary<string, Dictionary<string, Sprite>> _sprites = new Dictionary<string, Dictionary<string, Sprite>>(StringComparer.Ordinal);
        private readonly Dictionary<string, string> _skillText = new Dictionary<string, string>(StringComparer.Ordinal);
        private readonly Dictionary<string, string> _roles = new Dictionary<string, string>(StringComparer.Ordinal);
        private Uomd.Combat.Battle _battle;
        private VisualElement _root;
        private VisualElement _world;
        private VisualElement _unitLayer;
        private VisualElement _plateLayer;
        private VisualElement _fxLayer;
        private VisualElement _dock;
        private VisualElement _turnBar;
        private Label _hint;
        private Label _desc;
        private Button _autoButton;
        private AwaitableCompletionSource<PlayerAction> _pending;
        private SkillOption _selected;
        private TurnPrompt _prompt;
        private readonly List<BattleUnitView> _lunged = new List<BattleUnitView>();
        private bool _auto;
        private int _generation;

        public UomdScreenId ScreenId => UomdScreenId.Battle;

        public BattleScreenController(UomdSceneRouter router) => _router = router;

        private bool Calm => _router.Session.ReducedMotion;

        public async Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            int generation = ++_generation;
            _root = screenRoot;
            _views.Clear();
            _actions.Clear();
            _lunged.Clear();
            _auto = false;
            _pending = null;
            string encounterId = _router.Session.ActiveBattleEncounterId;
            _router.Audio.PlayBgmCue(AudioDirector.ResolveBattleMusicCue(encounterId, false));

            Dictionary<string, object> raw;
            try
            {
                string packJson = await _router.Patch.ReadTextAsync("units/unit_pack.json");
                string encounterJson = await _router.Patch.ReadTextAsync($"encounters/{encounterId}.json");
                raw = UomdJson.ParseObject(encounterJson);
                ReadSkillText(packJson);
                _battle = Uomd.Combat.Battle.Create(UnitPackDef.FromJson(packJson), EncounterDef.FromJson(encounterJson));
            }
            catch (Exception e)
            {
                Debug.LogError($"[Battle] encounter {encounterId} could not start: {e}");
                UomdUiKit.ShowToast(screenRoot, $"The battle could not start: {e.Message}");
                return;
            }

            BuildStage(raw);
            await LoadUnitArtAsync();
            if (generation != _generation) return;
            SyncViews();
            _ = RunAsync(generation);
        }

        private void ReadSkillText(string packJson)
        {
            _skillText.Clear();
            _roles.Clear();
            var pack = UomdJson.ParseObject(packJson);
            if (!(pack.TryGetValue("units", out object units) && units is List<object> list)) return;
            foreach (var u in list)
            {
                if (!(u is Dictionary<string, object> unit)) continue;
                _roles[Str(unit, "unit_id")] = Str(unit, "role");
                if (!(unit.TryGetValue("skills", out object skills) && skills is List<object> sk)) continue;
                foreach (var s in sk)
                {
                    if (s is Dictionary<string, object> skill && skill.TryGetValue("skill_id", out object id) && id is string sid
                        && skill.TryGetValue("description_en", out object d) && d is string text)
                    {
                        _skillText[sid] = text;
                    }
                }
            }
        }

        private static string Str(Dictionary<string, object> node, string key) => node.TryGetValue(key, out object v) && v is string s ? s : "";

        private void BuildStage(Dictionary<string, object> raw)
        {
            var stage = UomdScreenKit.Layer(_root, UomdThemeTokens.Void);
            stage.pickingMode = PickingMode.Position;
            var bg = UomdScreenKit.Backdrop(stage, _router.Media, _router.Media.Catalog.Background(Str(raw, "location_id")));
            bg.style.scale = new Scale(new Vector3(1.04f, 1.04f, 1f));
            UomdScreenKit.VerticalShade(stage, 0, 260, UomdThemeTokens.Void, 0f, 0.78f, fromBottom: true);
            UomdScreenKit.VerticalShade(stage, 0, 190, UomdThemeTokens.Void, 0.55f, 0f);

            // the formation lives in the 1920-wide reference band, centred on wider screens
            _world = new VisualElement { pickingMode = PickingMode.Ignore };
            _world.style.position = Position.Absolute;
            _world.style.left = new Length(50, LengthUnit.Percent);
            _world.style.marginLeft = -UomdScreenKit.RefWidth / 2f;
            _world.style.top = 0;
            _world.style.width = UomdScreenKit.RefWidth;
            _world.style.height = UomdScreenKit.RefHeight;
            stage.Add(_world);
            _unitLayer = UomdScreenKit.Layer(_world);
            _unitLayer.pickingMode = PickingMode.Ignore;
            _plateLayer = UomdScreenKit.Layer(_world);
            _fxLayer = UomdScreenKit.Layer(_world);

            string stageId = Str(raw, "stage_id"), title = Str(raw, "title_en");
            var head = UomdScreenKit.Text(stage, string.IsNullOrEmpty(stageId) ? title : $"{stageId}  ·  {title}", 32, UomdThemeTokens.GoldHi, 2f);
            head.AddToClassList("uomd-display");
            head.style.position = Position.Absolute;
            head.style.left = 60;
            head.style.top = 34;

            bool autoAllowed = !(raw.TryGetValue("ui", out object ui) && ui is Dictionary<string, object> u && u.TryGetValue("auto", out object a) && a is bool b && !b);
            if (autoAllowed) _autoButton = UomdScreenKit.AtRight(UomdScreenKit.MenuButton(stage, "AUTO", null, 176, 72, 24, false, ToggleAuto), 140, 66);

            _turnBar = new VisualElement { pickingMode = PickingMode.Ignore };
            _turnBar.style.position = Position.Absolute;
            _turnBar.style.left = 60;
            _turnBar.style.top = 128 - 27;
            _turnBar.style.height = 54;
            _turnBar.style.flexDirection = FlexDirection.Row;
            _turnBar.style.alignItems = Align.Center;
            stage.Add(_turnBar);
            _hint = UomdScreenKit.Centered(UomdScreenKit.Text(stage, "", 24, UomdThemeTokens.GoldHi, 2f), 0, 54);
            _hint.AddToClassList("uomd-display");
            _desc = UomdScreenKit.Centered(UomdScreenKit.Text(stage, "", 20, new Color(0.875f, 0.839f, 0.925f)), 0, 866);
            _desc.style.whiteSpace = WhiteSpace.Normal;
            _desc.style.width = 1360;
            _dock = UomdScreenKit.Layer(stage);
            _dock.pickingMode = PickingMode.Ignore;
        }

        private async Awaitable LoadUnitArtAsync()
        {
            var catalog = _router.Media.Catalog;
            foreach (var c in _battle.Combatants)
            {
                string unitId = c.Def.UnitId;
                if (_sprites.ContainsKey(unitId) || !catalog.TryGetUnitArt(unitId, out var art)) continue;
                var texture = await _router.Media.TextureAsync(art.AtlasPath);
                var frames = new Dictionary<string, Sprite>(StringComparer.Ordinal);
                if (texture != null)
                {
                    foreach (var kv in art.Frames)
                    {
                        var (x, y, w, h) = kv.Value;
                        // atlas frames are top-left [x, y, w, h]; Unity sprite rects are bottom-left
                        frames[kv.Key] = Sprite.Create(texture, new Rect(x, texture.height - (y + h), w, h), new Vector2(0.5f, 0f), 100f);
                    }
                }
                _sprites[unitId] = frames;
            }
        }

        /// <summary>Creates views for combatants that have none (start, reinforcements) and lays both sides out again.</summary>
        private void SyncViews()
        {
            foreach (string side in new[] { "player", "enemy" })
            {
                foreach (var (c, row, index, count) in VisualFormation(side))
                {
                    if (_views.ContainsKey(c.Id) || !_router.Media.Catalog.TryGetUnitArt(c.Def.UnitId, out var art)) continue;
                    var spot = UomdBattleFormation.SpotFor(side, row, index, count, _router.Session.BattleHudLayout);
                    var view = new BattleUnitView(_unitLayer, _plateLayer, c.Id, c.Def.NameEn, side, art,
                        _sprites.TryGetValue(c.Def.UnitId, out var frames) ? frames : new Dictionary<string, Sprite>(), spot, OnUnitTapped);
                    _views[c.Id] = view;
                }
            }
            // draw lower units in front
            foreach (var v in _views.Values.OrderBy(v => v.Y)) v.Root.BringToFront();
            Refresh();
        }

        /// <summary>
        /// BattleScene.visualFormationForSide: a side always reads as 2-front / 3-rear. An all-front wave keeps one unit in front
        /// (two when there are more than three) and moves the rest back; extra front units overflow to the rear, tanks first.
        /// </summary>
        private List<(Combatant c, string row, int index, int count)> VisualFormation(string side)
        {
            var list = _battle.Combatants.Where(c => c.Side == side && c.Objective == null && c.Alive).OrderBy(c => c.Slot).ToList();
            var rawFront = list.Where(c => c.Row == "front").ToList();
            var rawRear = list.Where(c => c.Row == "rear").ToList();
            var tank = new System.Text.RegularExpressions.Regex("pilgrim|knight|tank|guard|bulwark", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            List<Combatant> TanksFirst(List<Combatant> cs) => cs
                .Select((c, i) => (c, i))
                .OrderBy(x => tank.IsMatch(x.c.Def.UnitId + " " + (_roles.TryGetValue(x.c.Def.UnitId, out string role) ? role : "")) ? 0 : 1)
                .ThenBy(x => x.c.Slot).ThenBy(x => x.i).Select(x => x.c).ToList();
            List<Combatant> front, rear;
            if (rawFront.Count >= 2 && rawRear.Count == 0)
            {
                var sorted = TanksFirst(rawFront);
                int cap = rawFront.Count <= 3 ? 1 : 2;
                front = sorted.Take(cap).ToList();
                rear = sorted.Skip(cap).ToList();
            }
            else if (rawFront.Count > 2 && rawRear.Count < 3)
            {
                var sorted = TanksFirst(rawFront);
                front = sorted.Take(2).ToList();
                rear = sorted.Skip(2).Concat(rawRear).ToList();
            }
            else
            {
                front = rawFront;
                rear = rawRear;
            }
            return front.Select((c, i) => (c, "front", i, front.Count)).Concat(rear.Select((c, i) => (c, "rear", i, rear.Count))).ToList();
        }

        private void Refresh()
        {
            foreach (var c in _battle.Combatants)
            {
                if (!_views.TryGetValue(c.Id, out var v)) continue;
                v.SetHp(c.Hp, c.MaxHp);
                double ultimateCost = c.Def.Skills.Where(s => s.Type == "ultimate").Select(s => s.FocusCost).DefaultIfEmpty(0).Max();
                v.SetFocus(c.Focus, ultimateCost);
                if (c.Side == "enemy")
                {
                    var intent = c.Alive && _battle.Result == null ? _battle.IntentFor(c.Id) : null;
                    string target = intent?.TargetId != null ? _battle.Unit(intent.Value.TargetId).Def.NameEn.ToUpperInvariant() : null;
                    v.SetIntent(intent == null ? null : $"{(intent.Value.Announced ? "⚠ " : "")}{intent.Value.SkillName.ToUpperInvariant()}{(target != null ? $" → {target}" : "")}");
                }
            }
            RefreshTurnBar();
        }

        /// <summary>The next eight turns as medallions under the stage title (BattleScene.refreshHud).</summary>
        private void RefreshTurnBar()
        {
            _turnBar.Clear();
            var order = _battle.Result == null ? _battle.PreviewOrder(8) : new List<string>();
            if (order.Count == 0)
            {
                _turnBar.style.display = DisplayStyle.None;
                return;
            }
            _turnBar.style.display = DisplayStyle.Flex;
            _turnBar.style.backgroundColor = new Color(0.047f, 0.027f, 0.078f, 0.82f);
            _turnBar.style.borderTopLeftRadius = _turnBar.style.borderTopRightRadius = _turnBar.style.borderBottomLeftRadius = _turnBar.style.borderBottomRightRadius = 12;
            var rim = new Color(UomdThemeTokens.Gold.r, UomdThemeTokens.Gold.g, UomdThemeTokens.Gold.b, 0.52f);
            _turnBar.style.borderTopColor = _turnBar.style.borderBottomColor = _turnBar.style.borderLeftColor = _turnBar.style.borderRightColor = rim;
            _turnBar.style.borderTopWidth = _turnBar.style.borderBottomWidth = _turnBar.style.borderLeftWidth = _turnBar.style.borderRightWidth = 1.5f;
            _turnBar.style.paddingLeft = 16;
            _turnBar.style.paddingRight = 12;
            var label = UomdScreenKit.Text(_turnBar, "TURN", 14, UomdThemeTokens.GoldHi, 1f, bold: true);
            label.AddToClassList("uomd-display");
            label.style.marginRight = 14;
            for (int i = 0; i < order.Count; i++)
            {
                bool current = i == 0;
                var c = _battle.Unit(order[i]);
                float size = current ? 48f : 40f;
                var chip = new VisualElement { pickingMode = PickingMode.Ignore };
                chip.style.width = chip.style.height = size;
                chip.style.marginRight = 54 - size;
                chip.style.overflow = Overflow.Hidden;
                chip.style.borderTopLeftRadius = chip.style.borderTopRightRadius = chip.style.borderBottomLeftRadius = chip.style.borderBottomRightRadius = size / 2f;
                var ring = current ? UomdThemeTokens.GoldHi : c.Side == "player" ? UomdThemeTokens.PlayerSide : UomdThemeTokens.EnemySide;
                chip.style.borderTopColor = chip.style.borderBottomColor = chip.style.borderLeftColor = chip.style.borderRightColor = ring;
                chip.style.borderTopWidth = chip.style.borderBottomWidth = chip.style.borderLeftWidth = chip.style.borderRightWidth = current ? 2.5f : 1.5f;
                chip.style.backgroundColor = new Color(0.071f, 0.039f, 0.094f, 1f);
                if (_views.TryGetValue(c.Id, out var view) && view.IdleSprite != null)
                {
                    // the head: the idle frame scaled up and anchored at the top
                    var face = new VisualElement { pickingMode = PickingMode.Ignore };
                    face.style.position = Position.Absolute;
                    face.style.width = size * 1.9f;
                    face.style.height = size * 1.9f * view.IdleSprite.rect.height / Mathf.Max(1f, view.IdleSprite.rect.width);
                    face.style.left = -size * 0.45f;
                    face.style.top = -size * 0.12f;
                    face.style.backgroundImage = new StyleBackground(view.IdleSprite);
                    face.style.backgroundSize = new BackgroundSize(Length.Percent(100), Length.Percent(100));
                    chip.Add(face);
                }
                _turnBar.Add(chip);
            }
        }

        private async Awaitable RunAsync(int generation)
        {
            var step = _battle.Advance();
            await PlayEventsAsync(step.Events, generation);
            while (generation == _generation && _battle.Result == null)
            {
                PlayerAction action;
                if (_auto)
                {
                    await Awaitable.WaitForSecondsAsync(0.38f);
                    if (generation != _generation) return;
                    action = _battle.AutoAction();
                }
                else
                {
                    action = await AwaitPlayerActionAsync(_battle.Prompt());
                    if (generation != _generation) return;
                }
                _actions.Add(action);
                try
                {
                    step = _battle.Act(action);
                }
                catch (IllegalActionException e)
                {
                    _actions.RemoveAt(_actions.Count - 1);
                    UomdUiKit.ShowToast(_root, e.Message);
                    continue;
                }
                await PlayEventsAsync(step.Events, generation);
            }
            if (generation == _generation && _battle.Result != null) ShowResult(_battle.Result);
        }

        private Awaitable<PlayerAction> AwaitPlayerActionAsync(TurnPrompt prompt)
        {
            _pending = new AwaitableCompletionSource<PlayerAction>();
            _prompt = prompt;
            BuildSkillDock(prompt);
            return _pending.Awaitable;
        }

        private void Submit(PlayerAction action)
        {
            var pending = _pending;
            if (pending == null) return;
            _pending = null;
            ClearSkillDock();
            _router.Audio.PlaySfx("sfx_ui_confirm");
            pending.SetResult(action);
        }

        private void BuildSkillDock(TurnPrompt prompt)
        {
            ClearSkillDock();
            var actor = _battle.Unit(prompt.Actor);
            if (_views.TryGetValue(prompt.Actor, out var view)) view.SetActive(true);
            _hint.text = $"{actor.Def.NameEn.ToUpperInvariant()}'S TURN";
            var passive = actor.Def.Skills.FirstOrDefault(s => s.Type == "passive");
            _desc.text = passive != null ? $"Passive — {passive.NameEn}: {SkillText(passive.SkillId)}" : "";
            int n = prompt.Options.Count;
            float x0 = -((n - 1) * (CardWidth + CardGap)) / 2f;
            for (int i = 0; i < n; i++)
            {
                var o = prompt.Options[i];
                bool ultimate = o.Type == "ultimate";
                string kind = ultimate ? "★ ULTIMATE" : o.Type == "basic" ? "BASIC" : "SKILL";
                string sub = o.Available ? kind : o.Reason == "cooldown" ? $"CD {o.CooldownLeft}T" : $"FOCUS {actor.Focus}/{o.Def.FocusCost}";
                var card = UomdScreenKit.MenuButton(_dock, o.Name.ToUpperInvariant(), sub, CardWidth, CardHeight, 22, ultimate, () => OnSkillTapped(o));
                UomdScreenKit.Centered(card, x0 + i * (CardWidth + CardGap), 964);
                card.SetEnabled(o.Available);
                card.style.opacity = o.Available ? 1f : 0.44f;
                card.userData = o.SkillId;
            }
        }

        private string SkillText(string skillId) => _skillText.TryGetValue(skillId, out string text) ? text : "";

        private void ClearSkillDock()
        {
            _dock.Clear();
            _selected = null;
            _hint.text = "";
            _desc.text = "";
            foreach (var v in _views.Values)
            {
                v.SetSelectable(false);
                v.SetActive(false);
            }
        }

        private void OnSkillTapped(SkillOption o)
        {
            if (!o.Available || _pending == null) return;
            if (_selected != null && _selected.SkillId == o.SkillId)
            {
                // a second tap confirms when the skill needs no target or has a single legal one
                if (!o.NeedsTarget) Submit(new PlayerAction(o.SkillId));
                else if (o.LegalTargets.Count == 1) Submit(new PlayerAction(o.SkillId, o.LegalTargets[0]));
                return;
            }
            _selected = o;
            _router.Audio.PlaySfx("sfx_ui_tap");
            foreach (var card in _dock.Children())
            {
                bool selected = (card.userData as string) == o.SkillId;
                card.style.marginTop = selected ? -8 : 0;
                if (selected) card.AddToClassList("uomd-btn-primary");
                else if (!(_prompt?.Options.FirstOrDefault(x => x.SkillId == (card.userData as string))?.Type == "ultimate")) card.RemoveFromClassList("uomd-btn-primary");
            }
            foreach (var v in _views.Values) v.SetSelectable(false);
            _desc.text = SkillText(o.SkillId);
            if (o.NeedsTarget)
            {
                _hint.text = o.LegalTargets.Count == 1 ? "TAP THE SKILL AGAIN OR THE TARGET" : "CHOOSE A TARGET";
                foreach (string id in o.LegalTargets) if (_views.TryGetValue(id, out var v)) v.SetSelectable(true);
            }
            else
            {
                _hint.text = "TAP AGAIN TO CAST";
            }
        }

        private void OnUnitTapped(BattleUnitView view)
        {
            var o = _selected;
            if (o == null || !o.NeedsTarget || !o.LegalTargets.Contains(view.Id)) return;
            Submit(new PlayerAction(o.SkillId, view.Id));
        }

        /// <summary>True once the engine has a result (the capture pipeline waits for it).</summary>
        public bool Finished => _battle?.Result != null;

        /// <summary>Turns AUTO on (capture pipeline QA; the player uses the AUTO button).</summary>
        public void EnableAuto()
        {
            if (!_auto) ToggleAuto();
        }

        private void ToggleAuto()
        {
            _auto = !_auto;
            if (_auto) _autoButton?.AddToClassList("uomd-btn-primary");
            else _autoButton?.RemoveFromClassList("uomd-btn-primary");
            if (_auto && _pending != null && _battle.Result == null) Submit(_battle.AutoAction());
        }

        private async Awaitable PlayEventsAsync(List<Dictionary<string, object>> events, int generation)
        {
            foreach (var e in events)
            {
                if (generation != _generation) return;
                float wait = Present(e);
                if (wait > 0f) await Awaitable.WaitForSecondsAsync(Calm ? wait * 0.6f : wait);
            }
            if (generation != _generation) return;
            await SettleAsync();
            Refresh();
        }

        private static string S(Dictionary<string, object> e, string key) => e.TryGetValue(key, out object v) && v != null ? Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture) : "";
        private static double N(Dictionary<string, object> e, string key) => e.TryGetValue(key, out object v) && v != null ? Convert.ToDouble(v, System.Globalization.CultureInfo.InvariantCulture) : 0;
        private static bool B(Dictionary<string, object> e, string key) => e.TryGetValue(key, out object v) && v is bool b && b;

        /// <summary>Shows one engine event and returns how long to hold before the next (BattleScene.present timings).</summary>
        private float Present(Dictionary<string, object> e)
        {
            string type = S(e, "type");
            switch (type)
            {
                case "turn_start":
                {
                    foreach (var v in _views.Values) v.SetActive(false);
                    if (_views.TryGetValue(S(e, "actor"), out var actor))
                    {
                        actor.SetActive(true);
                        return actor.Side == "enemy" ? 0.22f : 0f;
                    }
                    return 0f;
                }
                case "skill_used":
                {
                    if (!_views.TryGetValue(S(e, "actor"), out var actor)) return 0.2f;
                    string skillType = S(e, "skillType");
                    var def = _battle.Unit(actor.Id).Def.Skills.FirstOrDefault(s => s.SkillId == S(e, "skill"));
                    if (skillType == "ultimate" || skillType == "active") Banner(def?.NameEn ?? S(e, "skill"), skillType == "ultimate");
                    var targets = e.TryGetValue("targets", out object t) && t is IEnumerable<object> list ? list.Select(x => x as string).Where(x => x != null).ToList() : new List<string>();
                    string state = skillType == "ultimate" ? "ultimate" : skillType == "active" ? "active" : "basic";
                    // a basic strike on one opponent closes the distance first
                    if (skillType == "basic" && targets.Count == 1 && _views.TryGetValue(targets[0], out var opp) && opp.Side != actor.Side && !Calm)
                    {
                        actor.Play("walk");
                        actor.MoveTo(opp.X + (actor.Side == "player" ? -135f : 135f), opp.Y, 240, Calm);
                        if (!_lunged.Contains(actor)) _lunged.Add(actor);
                        UomdScreenKit.After(actor.Root, 240, () => actor.Play(state));
                        return 0.5f;
                    }
                    actor.Play(state);
                    _router.Audio.PlaySfx(skillType == "ultimate" ? "sfx_blade_heavy" : "sfx_blade_slash");
                    return skillType == "basic" ? 0.28f : 0.36f;
                }
                case "damage":
                {
                    if (!_views.TryGetValue(S(e, "target"), out var target)) return 0.2f;
                    bool crit = B(e, "crit");
                    double amount = N(e, "amount"), absorbed = N(e, "absorbed");
                    target.Play("hit");
                    if (amount > 0) Float(target, crit ? $"-{amount}!" : $"-{amount}", crit ? new Color(1f, 0.847f, 0.420f) : Color.white, crit ? 64 : 46);
                    if (absorbed > 0) Float(target, amount == 0 ? "⛨ BLOCKED" : $"({absorbed} absorbed)", UomdThemeTokens.Shield, 30, amount == 0 ? 0 : 80);
                    var c = _battle.Unit(target.Id);
                    target.SetHp(N(e, "hpAfter"), c.MaxHp);
                    return crit ? 0.36f : 0.27f;
                }
                case "heal":
                {
                    if (!_views.TryGetValue(S(e, "target"), out var target)) return 0.1f;
                    Float(target, $"+{N(e, "amount")}", new Color(0.561f, 0.890f, 0.627f), 44);
                    target.SetHp(N(e, "hpAfter"), _battle.Unit(target.Id).MaxHp);
                    return 0.26f;
                }
                case "shield":
                    if (_views.TryGetValue(S(e, "target"), out var shielded)) Float(shielded, $"⛨ +{N(e, "amount")} SHIELD", UomdThemeTokens.Shield, 34);
                    return 0.2f;
                case "status_applied":
                    if (_views.TryGetValue(S(e, "target"), out var affected)) Float(affected, S(e, "status").Replace('_', ' ').ToUpperInvariant(), new Color(1f, 0.478f, 0.588f), 32);
                    return 0.19f;
                case "focus":
                {
                    if (!_views.TryGetValue(S(e, "unit"), out var v)) return 0f;
                    var c = _battle.Unit(v.Id);
                    double cost = c.Def.Skills.Where(s => s.Type == "ultimate").Select(s => s.FocusCost).DefaultIfEmpty(0).Max();
                    v.SetFocus(N(e, "total"), cost);
                    if (cost > 0 && N(e, "total") >= cost && N(e, "total") - N(e, "delta") < cost) Float(v, "ULTIMATE READY", UomdThemeTokens.GoldHi, 30);
                    return 0f;
                }
                case "turn_skipped":
                    if (_views.TryGetValue(S(e, "actor"), out var skipped)) Float(skipped, "◆ STAGGERED", new Color(1f, 0.478f, 0.588f), 34);
                    return 0.4f;
                case "defeat":
                    if (_views.TryGetValue(S(e, "unit"), out var fallen)) fallen.Defeat(Calm);
                    return 0.56f;
                case "wave_start":
                    _ = AddWaveAsync();
                    Banner($"WAVE {N(e, "wave")}", false);
                    return 0.6f;
                default:
                    return 0f;
            }
        }

        private async Awaitable AddWaveAsync()
        {
            await LoadUnitArtAsync();
            SyncViews();
        }

        /// <summary>Every unit that closed in during this step walks back to its spot (several can, with follow-ups).</summary>
        private async Awaitable SettleAsync()
        {
            if (_lunged.Count == 0) return;
            var moved = _lunged.ToList();
            _lunged.Clear();
            foreach (var unit in moved)
            {
                if (unit.Alive) unit.Play("walk");
                unit.MoveTo(unit.X, unit.Y, 220, Calm);
            }
            await Awaitable.WaitForSecondsAsync(0.24f);
            foreach (var unit in moved) if (unit.Alive) unit.Play("idle");
        }

        private void Float(BattleUnitView v, string text, Color color, float size, float dx = 0f)
        {
            var label = UomdScreenKit.Text(_fxLayer, text, size, color, 1f, bold: true);
            label.AddToClassList("uomd-display");
            label.style.position = Position.Absolute;
            label.style.left = v.X + dx - 200f;
            label.style.width = 400f;
            label.style.top = v.HeadY + 30f;
            UomdScreenKit.Move(label, 0, -115, 1100, 0, Calm, EasingMode.EaseOutCubic);
            UomdScreenKit.Fade(label, 0f, 580, 520, Calm);
            UomdScreenKit.After(_fxLayer, 1200, () => label.RemoveFromHierarchy());
        }

        private void Banner(string text, bool ultimate)
        {
            var box = new VisualElement { pickingMode = PickingMode.Ignore };
            box.AddToClassList("uomd-panel");
            box.style.paddingLeft = box.style.paddingRight = 60;
            box.style.paddingTop = box.style.paddingBottom = 14;
            if (ultimate) box.style.backgroundColor = new Color(UomdThemeTokens.Crimson.r, UomdThemeTokens.Crimson.g, UomdThemeTokens.Crimson.b, 0.9f);
            var label = UomdScreenKit.Text(box, text.ToUpperInvariant(), ultimate ? 52 : 40, UomdThemeTokens.GoldHi, 3f);
            label.AddToClassList("uomd-display");
            _fxLayer.Add(box);
            UomdScreenKit.Centered(box, 0, 282);
            box.style.opacity = 0f;
            UomdScreenKit.Fade(box, 1f, 190, 0, Calm);
            UomdScreenKit.Fade(box, 0f, 240, ultimate ? 900 : 640, Calm);
            UomdScreenKit.After(_fxLayer, (ultimate ? 900 : 640) + 300, () => box.RemoveFromHierarchy());
        }

        private void ShowResult(BattleResult result)
        {
            ClearSkillDock();
            bool won = result.Winner == "player";
            foreach (var v in _views.Values) if (v.Alive && v.Side == (won ? "player" : "enemy")) v.Play("victory");
            _router.Audio.PlaySfx(won ? "sfx_bell_sanctuary" : "sfx_bell_silver");
            var veil = UomdScreenKit.Layer(_root, new Color(0.020f, 0.012f, 0.039f, 0.72f));
            veil.pickingMode = PickingMode.Position;
            var title = UomdScreenKit.Centered(UomdScreenKit.Text(veil, won ? "VICTORY" : "DEFEAT", 96, won ? UomdThemeTokens.GoldHi : new Color(1f, 0.478f, 0.588f), 8f), 0, 360);
            title.AddToClassList("uomd-display");
            var stars = UomdScreenKit.Centered(UomdScreenKit.Text(veil, new string('★', result.Stars) + new string('☆', Math.Max(0, 3 - result.Stars)), 72, UomdThemeTokens.GoldHi, 12f), 0, 470);
            string hash = BattleReplay.LogHash(_battle);
            UomdScreenKit.Centered(UomdScreenKit.Text(veil, $"{result.Turns} turns  ·  {_actions.Count} actions  ·  logHash {hash.Substring(0, 12)}", 24, UomdThemeTokens.TextDim), 0, 550);
            Action next = _router.EntryFlow.InEntryBattle
                ? () => _ = _router.EntryFlow.BattleFinishedAsync(won)
                : () => _ = _router.NavigateToAsync(UomdScreenId.Home);
            string label = _router.EntryFlow.InEntryBattle && !won ? "TRY AGAIN" : "CONTINUE";
            UomdScreenKit.Centered(UomdScreenKit.MenuButton(veil, label, null, 500, 104, 34, true, next), 0, 680);
            veil.style.opacity = 0f;
            UomdScreenKit.Fade(veil, 1f, 600, 400, Calm);
            stars.style.scale = new Scale(new Vector3(1.3f, 1.3f, 1f));
            UomdScreenKit.ScaleTo(stars, 1f, 420, 600, Calm, EasingMode.EaseOutBack);
        }

        public void OnTick(float deltaTime)
        {
            foreach (var v in _views.Values) v.Tick(deltaTime);
        }

        public void OnExit()
        {
            _generation++;
            _pending = null;
            foreach (var frames in _sprites.Values)
            {
                foreach (var sprite in frames.Values) if (sprite != null) UnityEngine.Object.Destroy(sprite);
            }
            _sprites.Clear();
            _views.Clear();
        }
    }

    /// <summary>
    /// Post-tutorial patch page (port of apps/game/src/scenes/FinishScene.ts): the Main Theme over the dimmed forest while
    /// the background download stages the latest signed release, the status box with real progress, a truthful line about
    /// where the entry progress is saved, and rotating canon quotes. When the release is ready the client restarts: the
    /// staged release switches on without any network and the title treats the player as returning.
    /// </summary>
    public sealed class FinishScreenController : IUomdScreenController
    {
        private const string WaitingTitle = "THE ROAD IS BEING PREPARED";
        private const string WaitingBody = "Downloading and verifying the latest patch while the music plays. The game will restart automatically as soon as the patch finishes.";
        private const string ReadyTitle = "EVERYTHING IS INSTALLED";
        private const string ReadyBody = "Patch complete. Restarting client…";
        private const string UpToDateBody = "Your content is up to date. Restarting client…";
        private const string FailedBody = "The download could not finish. Check your connection and try again; nothing already downloaded is lost.";
        private const string UpdateRequired = "This version of the game is too old for the road ahead. Please update the app.";
        private const string Restart = "RESTART & ENTER GAME";
        private const string Restarting = "RESTARTING…";
        private const int RestartFadeMs = 1300;

        private static readonly (string Quote, string Speaker)[] Quotes =
        {
            ("“Beside it. Not behind you. I know the difference.”", "Fadyme  ·  The Whispering Ash"),
            ("“That stone is loose. Give me your hand.”  —  “For the stone, or for the whole road?”", "Mahmut & Fadyme"),
            ("“A flaw in the architecture of the loaf. Quite beyond my control.”", "Fadyme  ·  A Roof Before Dawn"),
            ("“Wait for my shield. Do not let them separate us.”", "Mahmut  ·  Oathless Vanguard"),
            ("“Stay a little while. Before you stand watch.”  —  “I am here.”", "Fadyme & Mahmut"),
            ("“The bell kept the village hours long before the war taught it to count the missing.”", "Chronicle of Veyrhold"),
            ("“I would rather we reached somewhere ordinary. With an especially ordinary supper.”", "Fadyme  ·  A Road Forgotten"),
            ("“Even your armour is asking for a rest. Hold still.”", "Fadyme  ·  Roadside Rest"),
            ("“We leave when there is light. No hurry.”  —  “And no walking two steps ahead.”", "Mahmut & Fadyme")
        };

        private enum Shown { None, Waiting, Ready, Failed }

        private readonly UomdSceneRouter _router;
        private VisualElement _stage;
        private VisualElement _quoteGroup;
        private Label _quoteText;
        private Label _quoteSpeaker;
        private Label _head;
        private Label _note;
        private Label _figures;
        private Label _saveLine;
        private VisualElement _track;
        private VisualElement _fill;
        private Button _action;
        private IDisposable _subscription;
        private PatchServiceStatus _pending;
        private Shown _shown;
        private int _quoteIndex;
        private bool _restarting;
        private bool _live;
        private string _readyBody = ReadyBody;

        public UomdScreenId ScreenId => UomdScreenId.Finish;

        public FinishScreenController(UomdSceneRouter router) => _router = router;

        public Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            _restarting = false;
            _shown = Shown.None;
            _live = true;
            _router.Audio.PlayBgmCue("bgm_main_theme");
            bool calm = _router.Session.ReducedMotion;
            var stage = _stage = UomdScreenKit.Layer(screenRoot, UomdThemeTokens.Void);
            var bg = UomdScreenKit.Backdrop(stage, _router.Media, _router.Media.Catalog.Background("forest_whispering_ash"));
            bg.style.opacity = 0.38f;
            bg.style.scale = new Scale(new Vector3(1.04f, 1.04f, 1f));

            const float cx = 0f;
            var box = new VisualElement { pickingMode = PickingMode.Ignore };
            box.AddToClassList("uomd-panel");
            box.style.width = 1460;
            box.style.height = 584;
            box.style.borderTopColor = box.style.borderBottomColor = box.style.borderLeftColor = box.style.borderRightColor = UomdThemeTokens.GoldHi;
            stage.Add(box);
            UomdScreenKit.Centered(box, cx, 488);
            _head = UomdScreenKit.Centered(UomdScreenKit.Text(stage, "", 50, UomdThemeTokens.GoldHi, 4f), cx, 265);
            _head.AddToClassList("uomd-display");
            _note = UomdScreenKit.Centered(UomdScreenKit.Text(stage, "", 32, UomdThemeTokens.TextPrimary), cx, 372);
            _note.style.whiteSpace = WhiteSpace.Normal;
            _note.style.width = 1200;
            _note.style.unityTextAlign = TextAnchor.MiddleCenter;

            _track = new VisualElement { pickingMode = PickingMode.Ignore };
            _track.style.width = 1080;
            _track.style.height = 28;
            _track.style.backgroundColor = new Color(0.035f, 0.020f, 0.055f, 0.95f);
            stage.Add(_track);
            UomdScreenKit.Centered(_track, cx, 492);
            _fill = new VisualElement { pickingMode = PickingMode.Ignore };
            _fill.style.width = new Length(0, LengthUnit.Percent);
            _fill.style.height = new Length(100, LengthUnit.Percent);
            _fill.style.backgroundColor = UomdThemeTokens.GoldHi;
            _track.Add(_fill);
            _figures = UomdScreenKit.Centered(UomdScreenKit.Text(stage, "", 28, UomdThemeTokens.TextDim), cx, 550);

            _saveLine = UomdScreenKit.Centered(UomdScreenKit.Text(stage, "", 24, UomdThemeTokens.TextDim), cx, 596);
            RenderSave(_router.Api.IsSignedIn ? null : false);
            _action = UomdScreenKit.Centered(UomdScreenKit.MenuButton(stage, Restart, null, 700, 104, 34, true, () => _ = OnActionAsync()), cx, 704);
            _action.style.display = DisplayStyle.None;

            var rule = new Color(UomdThemeTokens.Gold.r, UomdThemeTokens.Gold.g, UomdThemeTokens.Gold.b, 0.45f);
            var left = new VisualElement { pickingMode = PickingMode.Ignore };
            left.style.width = 402; left.style.height = 1.5f; left.style.backgroundColor = rule;
            stage.Add(left); UomdScreenKit.Centered(left, -219, 815);
            var right = new VisualElement { pickingMode = PickingMode.Ignore };
            right.style.width = 402; right.style.height = 1.5f; right.style.backgroundColor = rule;
            stage.Add(right); UomdScreenKit.Centered(right, 219, 815);

            _quoteGroup = UomdScreenKit.Layer(stage);
            _quoteIndex = UnityEngine.Random.Range(0, Quotes.Length);
            _quoteText = UomdScreenKit.Centered(UomdScreenKit.Text(_quoteGroup, Quotes[_quoteIndex].Quote, 36, UomdThemeTokens.TextPrimary, 0f, italic: true), cx, 870);
            _quoteText.style.whiteSpace = WhiteSpace.Normal;
            _quoteText.style.width = 1420;
            _quoteSpeaker = UomdScreenKit.Centered(UomdScreenKit.Text(_quoteGroup, "—  " + Quotes[_quoteIndex].Speaker, 22, UomdThemeTokens.GoldHi, 3f), cx, 944);
            _quoteSpeaker.AddToClassList("uomd-display");
            stage.schedule.Execute(CycleQuote).Every(4200).StartingIn(4200);

            // the background download reports from its own continuations; the screen renders the latest status each frame
            var service = _router.Patch.Service;
            _subscription = service.Subscribe(s => _pending = s);
            if (service.Status.Kind == PatchServiceKind.Idle) _ = service.StartAsync();
            Render(_pending ?? service.Status);
            _pending = null;

            stage.style.opacity = 0f;
            UomdScreenKit.Fade(stage, 1f, 1300, 0, calm);
            return UomdAwaitables.Completed();
        }

        private void Render(PatchServiceStatus s)
        {
            if (_restarting || !_live) return;
            if (s.Kind == PatchServiceKind.Ready)
            {
                if (_shown == Shown.Ready) return;
                _shown = Shown.Ready;
                var outcome = s.Outcome;
                bool downloaded = outcome != null && (outcome.Status == PatchStatus.Staged || outcome.Status == PatchStatus.Applied);
                _head.text = ReadyTitle;
                _note.text = _readyBody = downloaded ? ReadyBody : UpToDateBody;
                SetBar(1f, true);
                string release = outcome != null && (outcome.Status == PatchStatus.Staged || outcome.Status == PatchStatus.Applied) ? FormatReleaseTitle(outcome.ReleaseId) : "";
                _figures.text = release.Length > 0 ? $"100 %   ·   READY   ·   {release}" : "100 %   ·   READY";
                // QA captures hold on the ready page; a player is restarted automatically
                if (UomdCaptureRunner.Requested(out _)) ShowAction(Restart, true);
                else
                {
                    ShowAction(Restarting, false);
                    _ = RestartAsync();
                }
                return;
            }
            if (s.Kind == PatchServiceKind.Failed)
            {
                _shown = Shown.Failed;
                _head.text = WaitingTitle;
                _note.text = s.UpdateRequired ? UpdateRequired
                    : s.RequiresNetworkApproval ? "Downloads are paused on this data-saving connection."
                    : $"{FailedBody}\n{Truncate(s.Detail, 180)}";
                SetBar(0f, false);
                _figures.text = "";
                if (s.UpdateRequired) _action.style.display = DisplayStyle.None;
                else ShowAction(s.RequiresNetworkApproval ? "USE MOBILE DATA" : "TRY AGAIN", true);
                return;
            }
            _shown = Shown.Waiting;
            _head.text = WaitingTitle;
            _note.text = WaitingBody;
            ShowAction("PAUSE DOWNLOAD", true);
            float? fill = s.BarFill;
            SetBar(fill ?? 0f, true);
            var p = s.Progress;
            _figures.text = p != null && p.BytesTotal > 0 && p.Phase == PatchPhase.Downloading
                ? $"{Mathf.FloorToInt((fill ?? 0f) * 100f)} %   ·   {FormatBytes(p.BytesDone)} / {FormatBytes(p.BytesTotal)}"
                : PhaseText(p?.Phase);
        }

        private static string PhaseText(string phase) => phase switch
        {
            PatchPhase.Downloading => "Downloading game patch…",
            PatchPhase.Verifying => "Verifying signed manifest…",
            PatchPhase.Activating => "Applying update…",
            _ => "Checking for patches…"
        };

        /// <summary>apps/game/src/ui/format.ts formatBytes.</summary>
        public static string FormatBytes(long n) => n < 1024 * 1024
            ? $"{Math.Max(0, (long)Math.Round(n / 1024.0))} KB"
            : (n / (1024.0 * 1024.0)).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture) + " MB";

        /// <summary>"rel_0003_part1_campaign" → "Part I Campaign (rel_0003)"; other ids are shown as they are.</summary>
        public static string FormatReleaseTitle(string releaseId)
        {
            if (string.IsNullOrEmpty(releaseId)) return "";
            var m = System.Text.RegularExpressions.Regex.Match(releaseId.Trim(), @"^rel_(\d+)_(.+)$", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            if (!m.Success) return releaseId;
            var words = m.Groups[2].Value.Split('_').Select(w =>
            {
                var part = System.Text.RegularExpressions.Regex.Match(w, @"^part(\d+)$", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                if (part.Success) return part.Groups[1].Value switch { "1" => "Part I", "2" => "Part II", "3" => "Part III", var n => "Part " + n };
                return w.Length == 0 ? w : char.ToUpperInvariant(w[0]) + w.Substring(1);
            });
            return $"{string.Join(" ", words)} (rel_{m.Groups[1].Value})";
        }

        private static string Truncate(string text, int max) => string.IsNullOrEmpty(text) || text.Length <= max ? text ?? "" : text.Substring(0, max);

        private void SetBar(float fill, bool visible)
        {
            _track.style.display = visible ? DisplayStyle.Flex : DisplayStyle.None;
            _fill.style.width = new Length(Mathf.Clamp01(fill) * 100f, LengthUnit.Percent);
        }

        private void ShowAction(string label, bool enabled)
        {
            _action.style.display = DisplayStyle.Flex;
            if (_action.Q<Label>() is Label text) text.text = label;
            _action.SetEnabled(enabled);
        }

        /// <summary>R09: say truthfully where the entry progress is saved (null = saving, true = confirmed, false = failed or device only).</summary>
        private void RenderSave(bool? confirmed)
        {
            if (!_router.Api.IsSignedIn)
            {
                _saveLine.text = "Progress is saved on this device only. Sign in to keep it on your account.";
                _saveLine.style.color = UomdThemeTokens.TextDim;
                return;
            }
            _saveLine.text = confirmed == true ? "✓ Progress saved to your account"
                : confirmed == false ? "Not saved to your account yet — it is kept on this device and will be sent again"
                : "Saving progress to your account…";
            _saveLine.style.color = confirmed == true ? new Color(0.561f, 0.890f, 0.627f) : confirmed == false ? new Color(1f, 0.478f, 0.588f) : UomdThemeTokens.TextDim;
        }

        private void CycleQuote()
        {
            _quoteIndex = (_quoteIndex + 1) % Quotes.Length;
            UomdScreenKit.Fade(_quoteGroup, 0f, 420);
            UomdScreenKit.After(_quoteGroup, 440, () =>
            {
                _quoteText.text = Quotes[_quoteIndex].Quote;
                _quoteSpeaker.text = "—  " + Quotes[_quoteIndex].Speaker;
                UomdScreenKit.Fade(_quoteGroup, 1f, 420);
            });
        }

        private async Awaitable OnActionAsync()
        {
            if (_restarting) return;
            var service = _router.Patch.Service;
            switch (_shown)
            {
                case Shown.Waiting:
                    service.Cancel();
                    break;
                case Shown.Failed:
                    _ = service.RetryAsync(service.Status.RequiresNetworkApproval ? true : (bool?)null);
                    break;
                case Shown.Ready:
                    await RestartAsync();
                    break;
            }
        }

        private async Awaitable RestartAsync()
        {
            if (_restarting) return;
            _restarting = true;
            if (_action.Q<Label>() is Label label) label.text = _router.Api.IsSignedIn ? "SAVING TO ACCOUNT…" : Restarting;
            _action.SetEnabled(false);
            if (_router.Api.IsSignedIn)
            {
                try
                {
                    await _router.Api.PutEntryAsync(true, 3, true);
                    RenderSave(true);
                }
                catch (Exception e)
                {
                    Debug.LogWarning($"[Finish] entry checkpoint not confirmed: {e.Message}");
                    RenderSave(false);
                    _note.text = $"{_readyBody}\n\nCould not confirm your entry checkpoint on the server.";
                    ShowAction("RETRY SAVE & RESTART", true);
                    _restarting = false;
                    return;
                }
            }
            _router.Patch.EntryCompleted = true;
            _note.text = _readyBody;
            UomdScreenKit.Fade(_stage, 0f, RestartFadeMs, 0, _router.Session.ReducedMotion);
            await Awaitable.WaitForSecondsAsync(_router.Session.ReducedMotion ? 0.3f : RestartFadeMs / 1000f);
            if (!_live) return;
            // the restart: the staged release switches on without any network, then back through the title as a returning player
            await _router.Patch.ActivateStagedAsync();
            await _router.NavigateToAsync(UomdScreenId.Studio);
        }

        public void OnTick(float deltaTime)
        {
            var next = _pending;
            if (next == null) return;
            _pending = null;
            Render(next);
        }

        public void OnExit()
        {
            _live = false;
            _subscription?.Dispose();
            _subscription = null;
            _pending = null;
        }
    }
}
